#version 300 es
precision highp float;
precision highp int;
precision highp sampler2D;
layout(location = 0) out uvec4 result;
uniform bool flag;
bool bump(inout uint n){n++;return true;}
uint add(inout uint n,uint v){n+=v;return n;}
void main(){uint n=0u;bool b=false&&bump(n); result=uvec4(n);}

